INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (24, 0, 4, "カオリ（サマー）", 4, "2030/12/17 14:59:59", 0, "2019/07/31 12:00:00", 0, 1, 10021, 24015, 110501, "あうぅ～残念さ～\nマジムンに魂を\n奪われちゃったかな～？");
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (24, 0, 1, "カオリ（サマー）", 4, "2030/12/17 14:59:59", 0, "2019/07/31 12:00:00", 4, 2, 10021, 24016, 110501, "今日は踊りのキレも悪いよ～\nゴーヤーっぽいもの食べて、元気回復さ～！");
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (24, 0, 4, "カオリ（サマー）", 4, "2030/12/17 14:59:59", 0, "2019/07/31 12:00:00", 0, 3, 10021, 24017, 110501, "マジムンだらけで目が回るさ～！\nふらふらさ～！");
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (24, 0, 2, "カオリ（サマー）", 1, "2030/12/17 14:59:59", 0, "2019/07/31 12:00:00", 5.2, 4, 10021, 24018, 110501, "なんくるない、なんくるない\n次、頑張ればいいんだよ～！\n海で泳いで\nリフレッシュするさー！");
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (24, 0, 6, "カオリ（サマー）", 5, "2030/12/17 14:59:59", 0, "2019/07/31 12:00:00", 4.2, 5, 10021, 24019, 110501, "恥ずかしいところ\n見られちゃったね～\n水着？　水着のことじゃないよー？");
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (24, 0, 2, "カオリ（サマー）", 2, "2030/12/17 14:59:59", 0, "2019/07/31 12:00:00", 0, 6, 10021, 24020, 110501, "絶好調さ～！　この調子で\n海の平和を取り戻すよ～！\n楽しい夏が待ってるさ～！");
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (24, 0, 6, "カオリ（サマー）", 1, "2030/12/17 14:59:59", 0, "2019/07/31 12:00:00", 6.4, 7, 10021, 24021, 110501, "何匹で襲ってきたって\n私はマブイを落っことさないよ～！\nくしゅん！　あ……\n今のくしゃみで落っこちたかも～？");
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (24, 0, 2, "カオリ（サマー）", 2, "2030/12/17 14:59:59", 0, "2019/07/31 12:00:00", 0, 8, 10021, 24022, 110501, "ひーやーさーさー♪\n戦いの後は、踊りを踊って\n気分スッキリさ～！");
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (24, 0, 3, "カオリ（サマー）", 6, "2030/12/17 14:59:59", 0, "2019/07/31 12:00:00", 10.08, 9, 10021, 24023, 110501, "あれ～？　戦ってるうちに\n水着がどっか行っちゃった～？\nねぇキミ、どっかで見なかった～？\nなんで離れるさ～？");
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (24, 0, 2, "カオリ（サマー）", 1, "2030/12/17 14:59:59", 0, "2019/07/31 12:00:00", 5, 10, 10021, 24024, 110501, "まだまだ私は元気だよ～！\nマジムンでもなんでも、\nどんとこーいさー♪");
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (24, 0, 2, "カオリ（サマー）", 2, "2030/12/17 14:59:59", 0, "2019/07/31 12:00:00", 0, 11, 10021, 24025, 110501, "私の空手は世界最強さ～！\n夏の陽射しと青い海も合わされば、\n向かうところ敵なしだよー！");
